import{_ as t,o as a,c as r,a3 as i}from"./chunks/framework.DQ-7HQaQ.js";const u=JSON.parse('{"title":"Build from Ordo, not from scratch","description":"","frontmatter":{},"headers":[],"relativePath":"reuse/index.md","filePath":"reuse/index.md","lastUpdated":1794376220000}'),o={name:"reuse/index.md"};function n(s,e,d,c,l,p){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="build-from-ordo-not-from-scratch" tabindex="-1">Build from Ordo, not from scratch <a class="header-anchor" href="#build-from-ordo-not-from-scratch" aria-label="Permalink to &quot;Build from Ordo, not from scratch&quot;">​</a></h1><p><strong>Decision guide · reviewed November 10, 2026 · application implementation remains pending.</strong></p><p>The clean build should preserve Ordo&#39;s useful behavior while replacing the assumptions that would undermine a portable, evidence-backed research library. A new folder is not a reason to discard working ideas; an existing function is not proof that it is safe to transplant.</p><h2 id="the-important-discovery" tabindex="-1">The important discovery <a class="header-anchor" href="#the-important-discovery" aria-label="Permalink to &quot;The important discovery&quot;">​</a></h2><p>There are two substantially different implementations in <code>StudioOrdo/ordo</code>. The current rebuild contains a small Rust realtime gateway and TypeScript contracts. An accessible historical commit contains the larger Rust/SQLite daemon: DAG validation, transactional job creation, task leases, durable event replay, graph candidates and promotion records. <strong>Inspect both generations before implementing a replacement.</strong> Exact commits, paths and inspection ranges are in the <a href="./source-audit">source audit</a>.</p><table tabindex="0"><thead><tr><th>Subsystem</th><th>Best starting point</th><th>Action</th></tr></thead><tbody><tr><td>Durable jobs</td><td>Historical <code>kernel.rs</code>: DAG validation, compiled plan, idempotent creation, claims</td><td>Extract a narrow Rust module; strengthen lease fencing and failure tests</td></tr><tr><td>Durable events</td><td>Historical <code>events.rs</code>: transactional append and cursor replay</td><td>Adapt with authorization, retention and corruption handling</td></tr><tr><td>Knowledge review</td><td>Historical <code>knowledge_graph.rs</code>: candidates, evidence, promotion records</td><td>Preserve the lifecycle; redesign identity, claims and atomic publication</td></tr><tr><td>Worker contract</td><td>Current <code>lib/ordo/executor.ts</code> plus owner-only executor lab</td><td>Specify one versioned contract; do not copy inconsistent envelopes unchanged</td></tr><tr><td>Live interface</td><td>Current Rust gateway plus the streaming workshop</td><td>Keep adapter boundaries and batching; repair byte framing, termination and cancellation</td></tr><tr><td>UI projections</td><td>Current <code>lib/ordo/projection.ts</code></td><td>Keep explicit schema, visibility and limitations; replace timestamp/count cursors</td></tr><tr><td>Media and import steps</td><td>Owner-only executor lab</td><td>Review specific executors for later extraction; no private source in this public site</td></tr><tr><td>Hosting</td><td>Existing server studio and application release lessons</td><td>Reuse operational tests; do not reinstall over an uninspected host</td></tr></tbody></table><h2 id="read-in-this-order" tabindex="-1">Read in this order <a class="header-anchor" href="#read-in-this-order" aria-label="Permalink to &quot;Read in this order&quot;">​</a></h2><ol><li><a href="./source-audit">Source audit</a>: what exists, what was inspected, and why it matters.</li><li><a href="./harvest-plan">Harvest plan</a>: how to turn those sources into small, maintainable modules.</li><li><a href="./../engineering/twelve-factor">Twelve-factor design</a>: operational boundaries and explicit exceptions.</li><li><a href="./../engineering/examples">Executable examples</a>: small, synthetic failure cases that clarify the contracts.</li><li><a href="./../project/roadmap">Delivery roadmap</a>: dependency-ordered slices and acceptance evidence.</li></ol><h2 id="keep-adapt-replace-defer" tabindex="-1">Keep, adapt, replace, defer <a class="header-anchor" href="#keep-adapt-replace-defer" aria-label="Permalink to &quot;Keep, adapt, replace, defer&quot;">​</a></h2><p><strong>Keep</strong> means preserve a behavior and its tests after confirming dependencies and reuse rights. <strong>Adapt</strong> means retain the idea but change a boundary or invariant. <strong>Replace</strong> means the existing mechanism conflicts with this project&#39;s requirements. <strong>Defer</strong> means useful later, not required to prove the first workflow.</p><p>The priorities are not a wholesale rewrite of Ordo&#39;s business product. We do not import payments, CRM, growth accounting, public marketing shells, or broad autonomous command execution. The first useful result remains: import reports, resolve ambiguous mentions, review claims, publish a library, and answer with inspectable evidence.</p><h2 id="evidence-levels" tabindex="-1">Evidence levels <a class="header-anchor" href="#evidence-levels" aria-label="Permalink to &quot;Evidence levels&quot;">​</a></h2><p>This audit is a scoped static inspection, not a production security assessment or a claim that all donor tests passed. A source file containing a test is different from a test executed in this project. The new documentation examples exercise selected invariants; they are not the application runtime. <a href="./../status">Status</a> and actual CI runs distinguish those claims.</p><p>Private donor paths are owner-only references. Public CI must work without private repositories, provider credentials or the owner&#39;s research data. No license change, private-code publication, DNS cutover or server deployment is authorized by this audit.</p>',14)])])}const m=t(o,[["render",n]]);export{u as __pageData,m as default};
